INSERT INTO benefit_items_import VALUES
  ('fubon', '富邦人壽高枕無憂定期壽險', 1, '身故', '身故保險金', '分情況（看原文）', '第十條被保險人於本契約有效期間內身故者，本契約效力即行終止，本公司按下列二者之最大值給付「身故保險金」：一、保險金額。'),
  ('fubon', '富邦人壽高枕無憂定期壽險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十一條被保險人於本契約有效期間內，致成附表一所列完全失能程度之一者，本契約效力即行終止，本公司按下列二者之最大值給付「完全失能保險金」：一、保險金額。'),
  ('fubon', '富邦人壽樂溢定期壽險附約', 1, '身故', '身故保險金', '保額 × 1', '第十四條被保險人於本附約有效期間內身故者，本公司按保險金額給付「身故保險金」後，本附約效力即行終止。'),
  ('fubon', '富邦人壽樂溢定期壽險附約', 2, '完全失能', '完全失能保險金', '保額 × 1', '第十五條被保險人於本附約有效期間內致成附表一所列完全失能程度之一者，本公司按保險金額給付「完全失能保險金」後，本附約效力即行終止。'),
  ('fubon', '富邦人壽優世代遞減型定期壽險', 1, '身故', '身故保險金', '保額 × 1', '第十三條被保險人於本契約有效期間內身故者，本公司依身故時之當年度保險金額給付身故保險金後，本契約效力即行終止。'),
  ('fubon', '富邦人壽優世代遞減型定期壽險', 2, '樣身故', '樣身故保險金', NULL, '前項情形，本公司給付樣身故保險金或喪葬費用保險金後，如發現被保險人生還時，要保人或受益人應將該筆已領之退還已繳保險費或身故保險金或喪葬費用保險金歸還本公司，其間若有應給付保險金之情事發生者，仍'),
  ('fubon', '富邦人壽優世代遞減型定期壽險', 3, '完全失能', '完全失能保險金', '保額 × 1', '第十四條被保險人於本契約有效期間內致成附表二所列完全失能程度之一者，本公司依完全失能診斷確定時之當年度保險金額給付完全失能保險金後，本契約效力即行終止。'),
  ('fubon', '富邦人壽優世代平準型定期壽險', 1, '身故', '身故保險金', '保額 × 1', '第十三條被保險人於本契約有效期間內身故者，本公司依身故時之保險金額給付身故保險金後，本契約效力即行終止。'),
  ('fubon', '富邦人壽優世代平準型定期壽險', 2, '完全失能張', '完全失能張保險金', '保額 × 1', '第十四條被保險人於本契約有效期間內致成附表一所列完全失能程度之一者，本公司依完全失能診斷確定時之保險金額給付完全失能張保險金後，本契約效力即行終止。'),
  ('fubon', '富邦人壽優世代平準型定期壽險', 3, '完全失能', '完全失能保險金', NULL, '前項第一款及第十九條情形致被保險人完全失能時，本公司按第十四條的約定給付完全失能保險金。'),
  ('fubon', '富邦人壽安享定期壽險', 1, '身故', '身故保險金', '分情況（看原文）', '第十三條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付「身故保險金」後，本契約效力即行終止：一、身故時之保險金額。'),
  ('fubon', '富邦人壽安享定期壽險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十四條被保險人於本契約有效期間內，經醫院醫師診斷確定致成附表一所列完全失能程度之一者，本公司按下列三者之最大值給付「完全失能保險金」後，本契約效力即行終止：一、完全失能診斷確定時之保險金額。'),
  ('fubon', '富邦人壽網投e平安定期壽險', 1, '身故', '身故保險金', '保額 × 1', '第十三條被保險人於本契約有效期間內身故者，本公司按身故時之保險金額給付「身故保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽網投e平安定期壽險', 2, '完全失能', '完全失能保險金', '保額 × 1', '第十四條被保險人於本契約有效期間內致成附表一所列完全失能程度之一者，本公司按完全失能診斷確定時之保險金額給付「完全失能保險金」後，本契約效力即行終止。'),
  ('nanshan', '南山人壽美添樂退美元利率變動型還本終身保險(定期給付型)', 1, '生存還本', '生存還本保險金', '分情況（看原文）', '第十七條生存還本保險金的給付被保險人於本契約「保障期間」內且「保險年齡」達七十歲之保單週年日仍生存時，本公司給付第一次「生存還本保險金」，其後至被保險人「保險年齡」達一百一十歲之保單週年日止，每達保單週年日仍生存時，本公司將依要保人投保時所選擇下列其中一種週期，給付「生存還本保險金」：一、年給付型生存還本保險金：本公司於保單週年日按「基本保額」及「累計增額繳清保險基本保額」分別乘以「年給付型生存還本保險金」計算乘數（繳費期間三年：百分之六點'),
  ('nanshan', '南山人壽美添樂退美元利率變動型還本終身保險(定期給付型)', 2, '身故', '身故保險金', NULL, '第二十一條身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故時，如要保人指定一次性給付「身故保險金」，本公司按下列方式計算之「身故保險金」給付予受益人；'),
  ('nanshan', '南山人壽美添樂退美元利率變動型還本終身保險(定期給付型)', 3, '年給付型生存還本', '年給付型生存還本保險金', NULL, '繳費期間六年：百分之十二）所得金額後之總和給付「年給付型生存還本保險金」。'),
  ('nanshan', '南山人壽美添樂退美元利率變動型還本終身保險(定期給付型)', 4, '月給付型生存還本', '月給付型生存還本保險金', NULL, '二、月給付型生存還本保險金：本公司於約定生存屆滿起一年內之保單週月日以前款「基本保額」及「累計增額繳清保險基本保額」對應之「年給付型生存還本保險金」，按本契約預定利率分別換算為每月之金額，並依所得金額總和按月給付「月給付型生存還本保險金」。'),
  ('nanshan', '南山人壽美添樂退美元利率變動型還本終身保險(定期給付型)', 5, '完全失能', '完全失能保險金', NULL, '第二十三條完全失能保險金的給付被保險人在本契約有效期間內致成附表二所列完全失能等級之一者，經「醫院」診斷確定後，如要保人指定一次性給付「完全失能保險金」，本公司按下列方式計算之「完全失能保險金」給付予被保險人；'),
  ('nanshan', '南山人壽美添樂退美元利率變動型還本終身保險(定期給付型)', 6, '祝壽', '祝壽保險金', NULL, '繳費期間六年：5.3523）所得金額後之總和給付「祝壽保險金」，本契約效力即行終止。'),
  ('nanshan', '南山人壽優利成雙利率變動型還本終身保險(定期給付型)', 1, '生存還本', '生存還本保險金', '分情況（看原文）', '第十五條生存還本保險金的給付被保險人於本契約「保障期間」內且於第一保單年度屆滿仍生存時，本公司給付第一次「生存還本保險金」，其後至被保險人「保險年齡」達一百零九歲之保單年度末止，每屆滿一保單年度仍生存時，本公司將依要保人投保時所選擇下列其中一種週期，給付「生存還本保險金」：一、年給付型生存還本保險金：本公司於保單週年日按「基本保額」及「累計增額繳清保險基本保額」分別乘以附表三中所對應保單年度之年給付型生存還本保險金係數所得金額後'),
  ('nanshan', '南山人壽優利成雙利率變動型還本終身保險(定期給付型)', 2, '身故', '身故保險金', NULL, '第十九條身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故時，如要保人指定一次性給付「身故保險金」，本公司按下列方式計算之「身故保險金」給付予受益人；'),
  ('nanshan', '南山人壽優利成雙利率變動型還本終身保險(定期給付型)', 3, '年給付型生存還本', '年給付型生存還本保險金', '分情況（看原文）', '金」，其後至被保險人「保險年齡」達一百零九歲之保單年度末止，每屆滿一保單年度仍生存時，本公司將依要保人投保時所選擇下列其中一種週期，給付「生存還本保險金」：一、年給付型生存還本保險金：本公司於保單週年日按「基本保額」及「累計增額繳清保險基本保額」分別乘以附表三中所對應保單年度之年給付型生存還本保險金係數所得金額後之總和給付「年給付型生存還本保險金」。'),
  ('nanshan', '南山人壽優利成雙利率變動型還本終身保險(定期給付型)', 4, '月給付型生存還本', '月給付型生存還本保險金', NULL, '二、月給付型生存還本保險金：本公司於約定生存屆滿起一年內之保單週月日以前款「基本保額」及「累計增額繳清保險基本保額」對應之「年給付型生存還本保險金」，按本契約預定利率分別換算為每月之金額，並依所得金額總和按月給付「月給付型生存還本保險金」。'),
  ('nanshan', '南山人壽優利成雙利率變動型還本終身保險(定期給付型)', 5, '完全失能', '完全失能保險金', NULL, '第二十一條完全失能保險金的給付被保險人在本契約有效期間內致成附表二所列完全失能等級之一者，經「醫院」診斷確定後，如要保人指定一次性給付「完全失能保險金」，本公司按下列方式計算之「完全失能保險金」給付予被保險人；'),
  ('nanshan', '南山人壽優利成雙利率變動型還本終身保險(定期給付型)', 6, '祝壽', '祝壽保險金', '分情況（看原文）', '第十七條祝壽保險金的給付被保險人「保險年齡」達一百一十歲之保單年度末仍生存，且本公司未依第二十一條、第二十三條給付「完全失能保險金」或分期定期保險金而本契約仍有效時，本公司將視同本契約保險期間屆滿，並依下列二款計算所得金額之總和給付「祝壽保險金」，本契約效力即行終止：一、「基本保額」對應部分為下列二者中之最大值：（一）保險期間屆滿當時之「當年度保險金額」加計「基本保額」的百分之十八後之總和。'),
  ('nanshan', '南山人壽御利臻藏美元利率變動型終身壽險(定期給付型)', 1, '身故', '身故保險金', NULL, '前項情形，本公司依第十九條給付「身故保險金」或喪葬費用保險金後，如發現被保險人生還時，要保人或受益人應將該筆已領之退還已繳保險費或「身故保險金」或喪葬費用保險金歸還本公司，其間若有應給付保險金或增值回饋分'),
  ('nanshan', '南山人壽御利臻藏美元利率變動型終身壽險(定期給付型)', 2, '祝壽', '祝壽保險金', '分情況（看原文）', '第十七條祝壽保險金的給付被保險人「保險年齡」達一百一十歲之保單年度末仍生存，且本契約仍有效時，本公司將視同本契約保險期間屆滿，並分別以下列二款計算所得之金額，再依其總和給付「祝壽保險金」，本契約效力即行終止：一、「基本保額」對應部分為下列二者中之最大值：（一）保險期間屆滿當時之「當年度保險金額」。'),
  ('nanshan', '南山人壽滿福保美元利率變動型終身壽險(定期給付型)', 1, '身故', '身故保險金', NULL, '前項情形，本公司依第十九條給付「身故保險金」或喪葬費用保險金後，如發現被保險人生還時，要保人或受益人應將該筆已領之退還已繳保險費或「身故保險金」或喪葬費用保險金歸還本公司，其間若有應給付保險金或增值回饋分'),
  ('nanshan', '南山人壽滿福保美元利率變動型終身壽險(定期給付型)', 2, '完全失能', '完全失能保險金', NULL, '第二十一條完全失能保險金的給付被保險人在本契約有效期間內致成附表二所列完全失能等級之一者，經「醫院」診斷確定後，如要保人指定一次性給付「完全失能保險金」，本公司按下列方式計算之「完全失能保險金」給付予被保險人；'),
  ('nanshan', '南山人壽滿福保美元利率變動型終身壽險(定期給付型)', 3, '祝壽', '祝壽保險金', '分情況（看原文）', '第十七條祝壽保險金的給付被保險人「保險年齡」達一百一十歲之保單年度末仍生存，且本公司未依第二十一條、第二十三條給付「完全失能保險金」或分期定期保險金而本契約仍有效時，本公司將視同本契約保險期間屆滿，並分別以下列二款計算所得之金額，再依其總和給付「祝壽保險金」，本契約效力即行終止：一、「基本保額」對應部分為下列二者中之最大值：（一）保險期間屆滿當時之「當年度保險金額」。'),
  ('nanshan', '南山人壽豐傳保倍美元利率變動型終身壽險(定期給付型)', 1, '身故', '身故保險金', NULL, '前項情形，本公司依第十九條給付「身故保險金」或喪葬費用保險金後，如發現被保險人生還時，要保人或受益人應將該筆已領之退還已繳保險費或「身故保險金」或喪葬費用保險金歸還本公司，其間若有應給付保險金或增值回饋分'),
  ('nanshan', '南山人壽豐傳保倍美元利率變動型終身壽險(定期給付型)', 2, '完全失能', '完全失能保險金', NULL, '第二十一條完全失能保險金的給付被保險人在本契約有效期間內致成附表二所列完全失能等級之一者，經「醫院」診斷確定後，如要保人指定一次性給付「完全失能保險金」，本公司按下列方式計算之「完全失能保險金」給付予被保險人；'),
  ('nanshan', '南山人壽豐傳保倍美元利率變動型終身壽險(定期給付型)', 3, '祝壽', '祝壽保險金', '分情況（看原文）', '第十七條祝壽保險金的給付被保險人「保險年齡」達一百一十歲之保單年度末仍生存，且本公司未依第二十一條、第二十三條給付「完全失能保險金」或分期定期保險金而本契約仍有效時，本公司將視同本契約保險期間屆滿，並分別以下列二款計算所得之金額，再依其總和給付「祝壽保險金」，本契約效力即行終止：一、「基本保額」對應部分為下列二者中之最大值：（一）保險期間屆滿當時之「當年度保險金額」。'),
  ('nanshan', '南山人壽金佳多利利率變動型還本終身保險(定期給付型)', 1, '生存還本', '生存還本保險金', NULL, '第十五條生存還本保險金的給付被保險人於本契約「保障期間」內且於第一保單年度屆滿仍生存時，本公司給付第一次「生存還本保險金」，其後至被保險人「保險年齡」達九十八歲之保單年度末止，每屆滿一保單年度仍生存時，本公司將給付「生存還本保險金」。'),
  ('nanshan', '南山人壽金佳多利利率變動型還本終身保險(定期給付型)', 2, '身故', '身故保險金', NULL, '前項情形，本公司依第十九條給付「身故保險金」或喪葬費用保險金後，如發現被保險人生還時，要保人或受益人應將該筆已領之退還已繳保險費或「身故保險金」或喪葬費用保險金歸還本公司，其間若有應給付保險金或增值回饋分'),
  ('nanshan', '南山人壽金佳多利利率變動型還本終身保險(定期給付型)', 3, '完全失能', '完全失能保險金', NULL, '第二十一條完全失能保險金的給付被保險人在本契約有效期間內致成附表二所列完全失能等級之一者，經「醫院」診斷確定後，如要保人指定一次性給付「完全失能保險金」，本公司按下列方式計算之「完全失能保險金」給付予被保險人；'),
  ('nanshan', '南山人壽金佳多利利率變動型還本終身保險(定期給付型)', 4, '滿期', '滿期保險金', '分情況（看原文）', '第十七條滿期保險金的給付被保險人「保險年齡」達九十九歲之保單年度末仍生存，且本公司未依第二十一條、第二十三條給付「完全失能保險金」或分期定期保險金而本契約仍有效時，本公司將視同本契約保險期間屆滿，並依下列二款計算所得金額之總和給付「滿期保險金」，本契約效力即行終止：一、「基本保額」對應之「年繳保險費總和」加計「基本保額」的百分之一點二五後之總和。'),
  ('nanshan', '南山人壽御享樂活利率變動型還本終身保險(定期給付型)', 1, '生存還本', '生存還本保險金', '分情況（看原文）', '第十五條生存還本保險金的給付被保險人於本契約「保障期間」內且「保險年齡」達「生存還本保險金給付起始年齡」之保單週年日仍生存時，本公司給付第一次「生存還本保險金」，其後至被保險人「保險年齡」達九十九歲之保單週年日止，每屆滿一保單年度仍生存時，本公司將依要保人投保時所選擇下列其中一種週期，給付「生存還本保險金」：一、年給付型生存還本保險金：本公司於保單週年日按「基本保額」及「累計增額繳清保險基本保額」分別乘以百分之十所得數額後之總和給付「年給付型生存還本保險金」。'),
  ('nanshan', '南山人壽御享樂活利率變動型還本終身保險(定期給付型)', 2, '身故', '身故保險金', NULL, '前項情形，本公司依第十九條給付「身故保險金」或喪葬費用保險金後，如發現被保險人生還時，要保人或受益人應將該筆已領之退還已繳保險費或「身故保險金」或喪葬費用保險金歸還本公司，其間若有應給付保險金或增值回饋分'),
  ('nanshan', '南山人壽御享樂活利率變動型還本終身保險(定期給付型)', 3, '年給付型生存還本', '年給付型生存還本保險金', '分情況（看原文）', '年日仍生存時，本公司給付第一次「生存還本保險金」，其後至被保險人「保險年齡」達九十九歲之保單週年日止，每屆滿一保單年度仍生存時，本公司將依要保人投保時所選擇下列其中一種週期，給付「生存還本保險金」：一、年給付型生存還本保險金：本公司於保單週年日按「基本保額」及「累計增額繳清保險基本保額」分別乘以百分之十所得數額後之總和給付「年給付型生存還本保險金」。'),
  ('nanshan', '南山人壽御享樂活利率變動型還本終身保險(定期給付型)', 4, '月給付型生存還本', '月給付型生存還本保險金', NULL, '二、月給付型生存還本保險金：本公司於約定生存屆滿起一年內之保單週月日以前款「基本保額」及「累計增額繳清保險基本保額」對應之「年給付型生存還本保險金」，按本契約預定利率分別換算為每月之金額，並依所得金額總和按月給付「月給付型生存還本保險金」。'),
  ('nanshan', '南山人壽御享樂活利率變動型還本終身保險(定期給付型)', 5, '完全失能', '完全失能保險金', NULL, '第二十一條完全失能保險金的給付被保險人在本契約有效期間內致成附表二所列完全失能等級之一者，經「醫院」診斷確定後，如要保人指定一次性給付「完全失能保險金」，本公司按下列方式計算之「完全失能保險金」給付予被保險人；'),
  ('nanshan', '南山人壽御享樂活利率變動型還本終身保險(定期給付型)', 6, '滿期', '滿期保險金', '依已繳保費計算（看原文）', '第十七條滿期保險金的給付被保險人「保險年齡」達九十九歲之保單年度末仍生存，且本公司未依第二十一條、第二十三條給付「完全失能保險金」或分期定期保險金而本契約仍有效時，本公司將視同本契約保險期間屆滿，按「基本保額」及「累計增額繳清保險基本保額」分別對應之「年繳保險費總和」之合計數額給付「滿期保險金」，本契約效力即行終止。'),
  ('nanshan', '南山人壽御利臻鑽美元利率變動型終身壽險(定期給付型)', 1, '身故', '身故保險金', NULL, '前項情形，本公司依第十七條給付「身故保險金」或喪葬費用保險金後，如發現被保險人生還時，要保人或受益人應將該筆已領之退還已繳保險費或「身故保險金」或喪葬費用保險金歸還本公司，其間若有應給付保險金或增值回饋分'),
